  const result = deepMerge(base, override);
  console.log('deepMerge with null:', JSON.stringify(result));

  // Test arrays are replaced
  const base2 = { tags: ['a', 'b'] };
  const override2 = { tags: ['c'] };
  const result2 = deepMerge(base2, override2);
  console.log('Arrays replaced:', JSON.stringify(result2));

  // Test no mutation
  const base3 = { x: { y: 1 } };
  const override3 = { x: { z: 2 } };
  deepMerge(base3, override3);
  console.log('Base unchanged after merge:', JSON.stringify(base3));
}).catch(e => console.error('Error:', e.message));
