  // Test type conversion errors
  try {
    applyEnv({ port: 3000 }, { APP_PORT: 'notanumber' });
  } catch (e) {
    console.log('Number conversion error:', e.message);
  }

  try {
    applyEnv({ debug: true }, { APP_DEBUG: 'maybe' });
  } catch (e) {
    console.log('Boolean conversion error:', e.message);
  }
}).catch(e => console.error('Error:', e.message));
"

